import{_ as a,o as r,c as d,ag as e}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 18 章：让系统逐步变得可靠","description":"失败分类与观察指标、自动检查与人工检查、小步修改/回归验证/可恢复设计、把个人经验变成 Harness 资产；产出 Harness 改进清单。","frontmatter":{"title":"第 18 章：让系统逐步变得可靠","description":"失败分类与观察指标、自动检查与人工检查、小步修改/回归验证/可恢复设计、把个人经验变成 Harness 资产；产出 Harness 改进清单。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/18-reliability.md","filePath":"guide/18-reliability.md","lastUpdated":null}'),l={name:"guide/18-reliability.md"};function o(i,t,n,s,h,u){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="第-18-章-让系统逐步变得可靠" tabindex="-1">第 18 章：让系统逐步变得可靠 <a class="header-anchor" href="#第-18-章-让系统逐步变得可靠" aria-label="Permalink to &quot;第 18 章：让系统逐步变得可靠&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>Harness 搭好了，但它会「退化」：某天突然不灵了、某个任务老翻车、规则改坏了一整类任务。可靠性不是「搭好就完」，而是<strong>一套持续改进的循环</strong>：分类失败 → 观察指标 → 小步修改 → 回归验证 → 沉淀资产。本章产出<strong>Harness 改进清单</strong>，并给你一个判断「系统是否在变好」的观察方法。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>本书项目维护过程中，我总结出三类典型的「翻车」及其对策（都在第 5 章实测中有真实样本）：</p><table tabindex="0"><thead><tr><th>翻车类型</th><th>真实案例</th><th>对策</th></tr></thead><tbody><tr><td>越权读取</td><td>Qoder/Hermes 读了 input 外文件</td><td>验收清单加「边界检查」项</td></tr><tr><td>自检失真</td><td>Qoder 称 25 项全通过却漏报</td><td>不依赖自检，独立验收</td></tr><tr><td>展示不一致</td><td>WorkBuddy 产物 6 份 vs 变更 5 份</td><td>两处都看，以文件系统为准</td></tr></tbody></table><p><strong>可靠性的本质：把「偶发问题」变成「已知模式 + 固定对策」。</strong> 每遇到一次新问题，就更新清单——系统会随着使用越来越可靠，而不是越来越乱。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>失败先分类，再谈修复</strong>：输入问题（材料/描述）、执行问题（工具/权限）、输出问题（质量/格式）、系统问题（产品/规则）——修错类别等于白修；</li><li><strong>观察三个指标</strong>：一次通过率（不返工就完成的占比）、人工介入次数、返工成本（时间/积分）——长期跟踪，判断系统在变好还是变坏；</li><li><strong>小步修改 + 回归验证</strong>：一次只改一个组件，改完跑一遍「曾经翻车的任务」验证没被改坏；</li><li><strong>可恢复设计</strong>：每个高风险步骤都有「后悔药」：备份、独立输出目录、版本记录（第 8 章）；</li><li><strong>个人经验 → Harness 资产</strong>：每次修复都沉淀成清单、规则或 Skill——系统越用越「懂事」。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>失败分类（Failure taxonomy）</strong>：按原因给失败分门别类。白话解释：故障树——先判断是「料的问题、人的问题还是机器的问题」。</li><li><strong>一次通过率（First-pass rate）</strong>：不返工直接验收通过的任务占比。核心健康指标。</li><li><strong>回归验证（Regression check）</strong>：修改后，重跑历史任务确认没改坏原有能力。白话解释：修完这扇门，检查其他门没被撞坏。</li><li><strong>可恢复设计（Recoverable design）</strong>：任何步骤出错都有恢复路径（备份/撤销/重跑）。</li></ul><h2 id="harness-改进清单-模板" tabindex="-1">Harness 改进清单（模板） <a class="header-anchor" href="#harness-改进清单-模板" aria-label="Permalink to &quot;Harness 改进清单（模板）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>改进项</th><th>触发信号</th><th>修改动作</th><th>验证方式</th></tr></thead><tbody><tr><td>任务卡模板</td><td>同一类任务反复描述不清</td><td>补字段/口径</td><td>跑一次该类任务</td></tr><tr><td>权限卡</td><td>出现越权/误删</td><td>收紧边界</td><td>检查读写记录</td></tr><tr><td>验收清单</td><td>有漏检的问题</td><td>加检查项</td><td>用旧任务回归</td></tr><tr><td>规则文件</td><td>行为漂移/变差</td><td>修改或回滚</td><td>对比修改前后</td></tr><tr><td>Skill</td><td>技能输出不稳</td><td>迭代指令/参考</td><td>连续调用 3 次</td></tr><tr><td>CONTEXT.md</td><td>出现过时/污染</td><td>清理更新</td><td>核对日期与事实</td></tr><tr><td>易变信息表</td><td>价格/版本变化</td><td>更新并标注核验日期</td><td>对照官方页面</td></tr></tbody></table><h2 id="跟着做-跑一次改进循环" tabindex="-1">跟着做：跑一次改进循环 <a class="header-anchor" href="#跟着做-跑一次改进循环" aria-label="Permalink to &quot;跟着做：跑一次改进循环&quot;">​</a></h2><h3 id="第一步-记录一次失败" tabindex="-1">第一步：记录一次失败 <a class="header-anchor" href="#第一步-记录一次失败" aria-label="Permalink to &quot;第一步：记录一次失败&quot;">​</a></h3><p>用一个真实翻车（或上一个任务的失败）填：</p><blockquote><p>任务：<strong><strong>｜现象：</strong></strong>｜失败类别（输入/执行/输出/系统）：____</p></blockquote><h3 id="第二步-定位到具体组件" tabindex="-1">第二步：定位到具体组件 <a class="header-anchor" href="#第二步-定位到具体组件" aria-label="Permalink to &quot;第二步：定位到具体组件&quot;">​</a></h3><p>对照六层架构（第 16 章），判断问题出在哪层：上下文？权限？验证？——<strong>定位到层，再定位到组件（文件/清单/规则）。</strong></p><h3 id="第三步-小步修改" tabindex="-1">第三步：小步修改 <a class="header-anchor" href="#第三步-小步修改" aria-label="Permalink to &quot;第三步：小步修改&quot;">​</a></h3><p>一次只改一个组件。改前备份（复制旧版或写版本注释）。</p><h3 id="第四步-回归验证" tabindex="-1">第四步：回归验证 <a class="header-anchor" href="#第四步-回归验证" aria-label="Permalink to &quot;第四步：回归验证&quot;">​</a></h3><p>重跑「这次失败的同类任务」+ 1 个「历史成功任务」，确认：失败被修复，成功没被破坏。</p><h3 id="第五步-沉淀资产" tabindex="-1">第五步：沉淀资产 <a class="header-anchor" href="#第五步-沉淀资产" aria-label="Permalink to &quot;第五步：沉淀资产&quot;">​</a></h3><p>把对策写进 Harness 改进清单 + 相关规则/清单文件，更新复盘记录（第 10 章）。</p><h2 id="一个完整示例-一次真实的改进循环" tabindex="-1">一个完整示例（一次真实的改进循环） <a class="header-anchor" href="#一个完整示例-一次真实的改进循环" aria-label="Permalink to &quot;一个完整示例（一次真实的改进循环）&quot;">​</a></h2><ul><li><strong>失败记录</strong>：任务「整理材料生成 6 份文档」，Agent 自检称通过，实际待办全未勾选（Qoder 实测）；</li><li><strong>类别判断</strong>：输出质量问题，根源在「验证层」——自检不可信；</li><li><strong>组件定位</strong>：验收清单缺「独立核验」项；</li><li><strong>修改动作</strong>：验收清单增加两条：「①不采信自检结论，逐项独立检查；②检查待办/勾选状态与结论一致性」；</li><li><strong>回归验证</strong>：用该清单重跑同类任务，问题可被检出 ✅；历史任务未受影响 ✅；</li><li><strong>沉淀</strong>：该经验成为第 2 章「自检不可信」原则、第 10 章验收清单、第 6 章选择表「边界」维度评分依据——<strong>一次修复，多个资产受益。</strong></li></ul><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>改了 A 坏了 B</td><td>没做回归验证</td><td>每次修改后重跑历史任务</td></tr><tr><td>一个问题修好又复发</td><td>只改了现象没改根因</td><td>定位到组件层，改规则/清单</td></tr><tr><td>指标一直不更新</td><td>没跟踪</td><td>每月统计一次通过率、介入次数</td></tr><tr><td>系统越改越复杂</td><td>为修而修</td><td>用改进清单控制：只加有触发信号的项</td></tr><tr><td>失败记录记了就忘</td><td>没接回资产</td><td>每次失败必须落一条「改进项」</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>修改安全层组件（权限、审批）后，<strong>必须</strong>跑回归验证——安全改错比功能改错更危险；</li><li>沉淀的资产（规则、清单）注意脱敏，不要夹带个人信息；</li><li>「可靠」不等于「全自动」：人工检查点永远保留，指标只是帮助你决定检查密度。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>40 分钟：按「跟着做」跑一次完整改进循环（记录失败 → 定位组件 → 小步修改 → 回归验证 → 沉淀资产），并建立你的 Harness 改进清单（至少 3 项）。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>Harness 改进清单</strong>（含触发信号、修改动作、验证方式）+ 一次完整改进循环的记录。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>失败先分类：输入、执行、输出、系统；</li><li>跟踪三个指标：一次通过率、介入次数、返工成本；</li><li>小步修改 + 回归验证，一次只改一个组件；</li><li>可恢复设计给每个高风险步骤留后悔药；</li><li>至此第五篇完成：Harness 从概念（15）到架构（16）到多 Agent（17）到可靠性（18），下一步进入真实案例（第六篇）。</li></ol>',37)])])}const c=a(l,[["render",o]]);export{g as __pageData,c as default};
